script:
(function () {
  'use strict';
  // An existing fixed-rate loan: where it stands after the payments made so far.
  //   Monthly rate i = rate / 12; payment P = L x i / (1 - (1 + i)^-n) (L / n at 0%), rounded to the
  //   cent as lenders do; the last payment clears whatever is left.
  //   If the payment is known instead, i is solved by bisection so that P amortizes L over n months
  //   (0% when P x n = L; impossible when P x n < L).
  //   Balance after k payments, interest to date and interest still to come come from the
  //   payment-by-payment schedule.
  // Checked in Node (scratchpad tests/w3b6_loans/exl.test.js): $12,000 at 7.5% over 36 months ->
  //   $373.27 a month; balance after 12 payments matches the closed form L(1+i)^k - P((1+i)^k - 1)/i;
  //   ($8,295.12 after 12), interest so far + still to come = total interest ($774.36 + $663.54);
  //   $12,000 / 36 months / $380 solves to 8.714%, matching an independent Python bisection, and that
  //   rate reproduces the $380.00 payment; $333.3334 x 36 = L gives 0%; a payment too small to repay
  //   the loan shows an error; 0 payments made gives the original balance, all n made gives $0.
  var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var last = null;

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function read(id) {
    var raw = String(el(id).value).trim();
    if (raw === '') return NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  // ---- Dates ----
  function daysFromCivil(y, m, d) {
    y -= m <= 2 ? 1 : 0;
    var era = Math.floor(y / 400), yoe = y - era * 400;
    var doy = Math.floor((153 * ((m + 9) % 12) + 2) / 5) + d - 1;
    var doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
    return era * 146097 + doe - 719468;
  }
  function civilFromDays(z) {
    z += 719468;
    var era = Math.floor(z / 146097), doe = z - era * 146097;
    var yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
    var doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
    var mp = Math.floor((5 * doy + 2) / 153);
    var d = doy - Math.floor((153 * mp + 2) / 5) + 1, m = mp < 10 ? mp + 3 : mp - 9;
    return { y: yoe + era * 400 + (m <= 2 ? 1 : 0), m: m, d: d };
  }
  function parseDate(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s || '').trim());
    if (!m) return NaN;
    var y = +m[1], mo = +m[2], d = +m[3];
    if (mo < 1 || mo > 12 || d < 1 || d > 31) return NaN;
    var z = daysFromCivil(y, mo, d), c = civilFromDays(z);
    return c.y === y && c.m === mo && c.d === d ? z : NaN;
  }
  function fmt(z) { var c = civilFromDays(z); return MONTHS[c.m - 1] + ' ' + c.d + ', ' + c.y; }
  function daysInMonth(y, m) { return daysFromCivil(m === 12 ? y + 1 : y, m === 12 ? 1 : m + 1, 1) - daysFromCivil(y, m, 1); }
  function addMonths(z, k) {
    var c = civilFromDays(z), t = (c.m - 1) + k, y = c.y + Math.floor(t / 12), m = ((t % 12) + 12) % 12 + 1;
    return daysFromCivil(y, m, Math.min(c.d, daysInMonth(y, m)));
  }

  // ---- Maths ----
  function payment(loan, i, n) { return i === 0 ? loan / n : loan * i / (1 - Math.pow(1 + i, -n)); }

  // Monthly rate that makes `pay` amortize `loan` over n months; NaN if the payment can't repay it.
  function solveRate(loan, pay, n) {
    if (pay * n < loan - 0.005) return NaN;
    if (pay * n <= loan + 0.005) return 0;
    var lo = 0, hi = 1;
    while (payment(loan, hi, n) < pay && hi < 1e6) hi *= 2;
    for (var it = 0; it < 200; it++) {
      var mid = (lo + hi) / 2;
      if (payment(loan, mid, n) < pay) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }

  function schedule(loan, i, n, pay) {
    var bal = loan, rows = [], total = 0;
    for (var k = 1; k <= n; k++) {
      var interest = bal * i, principal;
      if (k === n || bal + interest <= pay + 0.005) principal = bal; else principal = pay - interest;
      bal -= principal;
      if (Math.abs(bal) < 1e-7) bal = 0;
      total += interest;
      rows.push({ k: k, payment: interest + principal, interest: interest, principal: principal, balance: bal });
      if (bal === 0) break;
    }
    return { rows: rows, interest: total };
  }

  function standing(rows, made, loan) {
    var s = { interestPaid: 0, principalPaid: 0, paid: 0, interestLeft: 0, principalLeft: 0, left: 0 };
    rows.forEach(function (r) {
      if (r.k <= made) { s.interestPaid += r.interest; s.principalPaid += r.principal; s.paid += r.payment; }
      else { s.interestLeft += r.interest; s.principalLeft += r.principal; s.left += r.payment; }
    });
    s.balance = made === 0 ? loan : (rows[Math.min(made, rows.length) - 1].balance);
    s.countLeft = Math.max(0, rows.length - made);
    return s;
  }

  // ---- Output ----
  function renderSchedule() {
    var head = el('exlHead'), body = el('exlSchedule');
    if (!last) { head.innerHTML = ''; body.innerHTML = ''; return; }
    var view = el('exlView').value, rows = last.rows, html = [];
    if (view === 'year') {
      head.innerHTML = '<tr><th scope="col">Loan year</th><th scope="col">Payments</th><th scope="col">Interest</th><th scope="col">Principal</th><th scope="col">Ending balance</th><th scope="col">Status</th></tr>';
      var acc = null;
      rows.forEach(function (r, idx) {
        var y = Math.floor((r.k - 1) / 12) + 1;
        if (!acc || acc.y !== y) { if (acc) html.push(acc); acc = { y: y, p: 0, i: 0, pr: 0, b: 0, paid: 0, count: 0 }; }
        acc.p += r.payment; acc.i += r.interest; acc.pr += r.principal; acc.b = r.balance; acc.count++;
        if (r.k <= last.made) acc.paid++;
        if (idx === rows.length - 1) html.push(acc);
      });
      html = html.map(function (a) {
        var status = a.paid === a.count ? 'Paid' : (a.paid > 0 ? a.paid + ' of ' + a.count + ' paid' : 'To come');
        return '<tr><td>' + a.y + '</td><td>' + money.format(a.p) + '</td><td>' + money.format(a.i) + '</td><td>' + money.format(a.pr) + '</td><td>' +
          money.format(a.b) + '</td><td>' + status + '</td></tr>';
      });
    } else {
      var dated = !isNaN(last.first);
      head.innerHTML = '<tr><th scope="col">#</th>' + (dated ? '<th scope="col">Due</th>' : '') + '<th scope="col">Payment</th><th scope="col">Interest</th><th scope="col">Principal</th><th scope="col">Balance</th><th scope="col">Status</th></tr>';
      rows.forEach(function (r) {
        if (view === 'left' && r.k <= last.made) return;
        html.push('<tr><td>' + r.k + '</td>' + (dated ? '<td>' + fmt(addMonths(last.first, r.k - 1)) + '</td>' : '') + '<td>' + money.format(r.payment) + '</td><td>' +
          money.format(r.interest) + '</td><td>' + money.format(r.principal) + '</td><td>' + money.format(r.balance) + '</td><td>' + (r.k <= last.made ? 'Paid' : 'To come') + '</td></tr>');
      });
      if (!html.length) html.push('<tr><td colspan="' + (dated ? 7 : 6) + '">Every payment has been made.</td></tr>');
    }
    body.innerHTML = html.join('');
  }
  function clear() {
    ['exlBalance', 'exlPaidInt', 'exlLeftInt', 'exlLeft', 'exlSolved', 'exlSummary'].forEach(function (id) { setText(id, '–'); });
    el('exlSplit').innerHTML = '';
    last = null;
    renderSchedule();
  }

  function update() {
    var know = el('exlKnow').value;
    el('exlRateWrap').hidden = know !== 'rate';
    el('exlPayWrap').hidden = know === 'rate';
    setText('exlSolvedLabel', know === 'rate' ? 'Monthly payment' : 'Interest rate');
    var loan = read('exlLoan'), n = read('exlTerm'), rate = read('exlRate'), pay = read('exlPay'), made = read('exlMade');
    var firstRaw = String(el('exlFirst').value).trim(), first = firstRaw === '' ? NaN : parseDate(firstRaw);
    var err = el('exlError'), msg = '', i = 0;
    if (isNaN(loan) || isNaN(n) || isNaN(made)) msg = 'Enter the original loan amount, term and payments made.';
    else if (loan <= 0 || loan > 1e10) msg = 'Enter a loan amount above $0.';
    else if (n < 1 || n > 600 || n % 1 !== 0) msg = 'Enter an original term of 1 to 600 whole months.';
    else if (made < 0 || made > n || made % 1 !== 0) msg = 'Enter 0 to ' + n + ' payments made so far.';
    else if (know === 'rate' && (isNaN(rate) || rate < 0 || rate > 50)) msg = 'Enter an interest rate from 0% to 50%.';
    else if (know !== 'rate' && (isNaN(pay) || pay <= 0 || pay > 1e10)) msg = 'Enter your monthly payment.';
    else if (firstRaw !== '' && isNaN(first)) msg = 'Enter a valid first payment date, or leave it blank.';
    if (!msg && know !== 'rate') {
      i = solveRate(loan, pay, n);
      if (isNaN(i)) msg = 'A payment of ' + money.format(pay) + ' for ' + n + ' months adds up to less than the loan amount, so it can\'t repay it. Check the payment and term.';
      else if (i * 12 > 0.5) msg = 'That payment implies an interest rate above 50%. Check the payment and term.';
    }
    err.hidden = !msg;
    err.textContent = msg;
    if (msg) { clear(); return; }

    if (know === 'rate') { i = rate / 100 / 12; pay = Math.round(payment(loan, i, n) * 100) / 100; }
    var sch = schedule(loan, i, n, pay), st = standing(sch.rows, made, loan);
    last = { rows: sch.rows, made: made, first: first };
    setText('exlBalance', money.format(st.balance));
    setText('exlPaidInt', money.format(st.interestPaid));
    setText('exlLeftInt', money.format(st.interestLeft));
    setText('exlLeft', String(st.countLeft));
    setText('exlSolved', know === 'rate' ? money.format(pay) : (Math.round(i * 12 * 100000) / 1000).toFixed(3) + '%');

    var s;
    if (st.countLeft === 0) s = 'All ' + sch.rows.length + ' payments have been made: the loan is paid off. It cost ' + money.format(sch.interest) + ' in interest.';
    else {
      var timeShare = made / sch.rows.length, princShare = (loan - st.balance) / loan;
      s = 'After ' + made + ' of ' + sch.rows.length + ' payments (' + Math.round(timeShare * 100) + '% of the term) you have repaid ' +
        Math.round(princShare * 100) + '% of the principal. ';
      if (made > 0 && st.interestPaid > 0) s += Math.round(st.interestPaid / st.paid * 100) + '% of what you have paid so far went to interest. ';
      s += 'You still owe ' + money.format(st.balance) + ' and will pay ' + money.format(st.interestLeft) + ' more in interest';
      s += !isNaN(first) ? ', with the last payment due ' + fmt(addMonths(first, sch.rows.length - 1)) + '.' : '.';
    }
    setText('exlSummary', s);
    var lines = [
      ['Payments', String(made), String(st.countLeft), String(sch.rows.length)],
      ['Principal', money.format(st.principalPaid), money.format(st.principalLeft), money.format(loan)],
      ['Interest', money.format(st.interestPaid), money.format(st.interestLeft), money.format(sch.interest)],
      ['Total paid', money.format(st.paid), money.format(st.left), money.format(st.paid + st.left)]
    ];
    el('exlSplit').innerHTML = lines.map(function (l) {
      return '<tr><th scope="row">' + l[0] + '</th><td>' + l[1] + '</td><td>' + l[2] + '</td><td>' + l[3] + '</td></tr>';
    }).join('');
    renderSchedule();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('exlForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('exlView').addEventListener('change', renderSchedule);
    update();
  });
})();
